using System.Net;using System.Text;using System.Text.RegularExpressions;using System.Text.Json;using Kaji.KajiMultipart;
class Driver:HttpMessageHandler {
 public int Calls;
 protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken cancellationToken){
  Calls++;var type=request.Content!.Headers.ContentType!;if(type.MediaType!="multipart/form-data")throw new Exception("media");var boundary=type.Parameters.Single(p=>p.Name=="boundary").Value!.Trim('"');
  var raw=Encoding.Latin1.GetString(await request.Content.ReadAsByteArrayAsync(cancellationToken));var chunks=raw.Split("--"+boundary,StringSplitOptions.None);if(chunks.Length!=12||chunks[0]!=""||chunks[11]!="--\r\n")throw new Exception("boundaries");var parsed=new Dictionary<string,List<byte[]>>();
  for(int i=1;i<11;i++){var part=chunks[i];if(!part.StartsWith("\r\n")||!part.EndsWith("\r\n"))throw new Exception("CRLF");part=part[2..^2];int split=part.IndexOf("\r\n\r\n",StringComparison.Ordinal);var header=part[..split];var match=Regex.Match(header,"name=\"?([^\";\\r\\n]+)\"?");var name=match.Groups[1].Value.Trim();if(!parsed.ContainsKey(name))parsed[name]=new();parsed[name].Add(Encoding.Latin1.GetBytes(part[(split+4)..]));if(name=="chunking_strategy"&&!header.Contains("application/json"))throw new Exception("JSON part content type");}
  using var metadata=JsonDocument.Parse(parsed["chunking_strategy"][0]);var root=metadata.RootElement;if(root.GetProperty("type").GetString()!="server_vad"||root.GetProperty("label").GetString()!="café雪"||root.GetProperty("threshold").GetDouble()!=0.5)throw new Exception("union JSON wire");
  var items=parsed["timestamp_granularities[]"];if(items.Count!=2||Encoding.UTF8.GetString(items[0])!="word"||Encoding.UTF8.GetString(items[1])!="segment")throw new Exception("repeated array");
  if(parsed["files"].Count!=2)throw new Exception("file array repetition");using var extra=JsonDocument.Parse(parsed["extra"][0]);if(extra.RootElement.GetProperty("snow").GetString()!="雪")throw new Exception("open object JSON part");
  return new HttpResponseMessage(HttpStatusCode.NoContent){Content=new ByteArrayContent(Array.Empty<byte>())};
 }
}
class Probe {static async Task Main(){var driver=new Driver();var client=new KajiClient(new HttpClient(driver),new KajiClientOptions{BaseUrl="https://unused.example"});var body=new UploadThingMultipartBody{Title="café雪",Flag=false,Count=0,File=new MultipartFile(new byte[]{0,255},"blob.bin"),ChunkingStrategy=JsonSerializer.SerializeToElement(new{type="server_vad",label="café雪",threshold=0.5}),TimestampGranularities=new(){"word","segment"},Files=new(){new MultipartFile(new byte[]{0,255}),new MultipartFile(new byte[]{1,254})},KajiExtraParts=new Dictionary<string,object?>{{"extra",new{snow="雪"}}}};await client.UploadThingAsync(body);if(driver.Calls!=1)throw new Exception("attempts");}}
